SRC_CALLS = {
    "left > 0 ? 'Bu ay ${formatCount(left)} organizasyon hakkın kaldı.' : 'Bu ayın organizasyon hakkı doldu. Paketi yükselterek artırabilirsin.'":
        'left > 0 ? eventsL10n.eventsLeft(left) : eventsL10n.eventsLimitReached',
    "'${ratingLabel(avg)} · organizasyonlarına ${formatCount(data.ratingCount)} değerlendirme'": 'eventsL10n.groupRating(ratingLabel(avg), data.ratingCount)',
    "'${e.title} · ${formatDate(e.startsAt.toLocal())}'": 'eventsL10n.titleOnDate(e.title, formatDate(e.startsAt.toLocal()))',
    "'Bekleme listesine girdin (${value.place}. sıra). Yer açılınca haber vereceğiz.'": 'eventsL10n.waitlistJoined(value.place ?? 0)',
    "'• ${c.title} · ${formatDateTime(c.startsAt.toLocal())}'": 'eventsL10n.conflictLine(c.title, formatDateTime(c.startsAt.toLocal()))',
    "'${person.displayName} katılımcı oldu.'": 'eventsL10n.approvedPerson(person.displayName)',
    "'İstek reddedildi; ${person.displayName} bilgilendirildi.'": 'eventsL10n.declinedPerson(person.displayName)',
    "'${e.group.name} grubuna katıl'": 'eventsL10n.joinGroupFirst(e.group.name)',
    "'${e.title} · GWAY\\'de katıl:'": 'eventsL10n.eventShareText(e.title)',
    "'${series.label} · ${formatDate(series.until!)} tarihine kadar'": 'eventsL10n.seriesUntil(series.label, formatDate(series.until!))',
    "'Katılım ücreti: ${e.fee!.label}'": 'eventsL10n.fee(e.fee!.label)',
    "'${c.title} · ${formatDateTime(c.startsAt.toLocal())}'": 'eventsL10n.titleOnDate(c.title, formatDateTime(c.startsAt.toLocal()))',
    "'Katılım istekleri (${requests.length})'": 'eventsL10n.joinRequestsCount(requests.length)',
    "'${e.goingCount} katılandan $confirmed kişi geleceğini teyit etti.'": 'eventsL10n.confirmedOf(e.goingCount, confirmed)',
    "'${p.displayName} · teyit etti'": 'eventsL10n.confirmedName(p.displayName)',
    "'Değerlendirmeler (${reviews.length})'": 'eventsL10n.reviewsCount(reviews.length)',
    "'${entry.person.displayName} geldi olarak işaretlendi.'": 'eventsL10n.markedCame(entry.person.displayName)',
    "'${entry.person.displayName} gelmedi olarak işaretlendi.'": 'eventsL10n.markedMissed(entry.person.displayName)',
    "'$hours saat önce'": 'eventsL10n.hoursBefore(hours)',
    "'$star yıldız'": 'eventsL10n.starsLabel(star)',
    """'Bu tarihte ilinde aynı kategoride $n organizasyon daha var. Üyelerin seçim yapmak zorunda kalmasın '
        'istersen başka bir gün seçebilirsin.'""": 'eventsL10n.sameDayOthers(n)',
    "'İpucu: ${event.location}'": 'eventsL10n.hint(event.location)',
    "'İpucu: ${event.location} · Katılanlara $when açıklanacak.'": 'eventsL10n.hintRevealAt(event.location, when)',
    "'Mekan $when katılanlara açıklanacak.'": 'eventsL10n.venueRevealAt(when)',
}
